// ============================================================
// Módulo Notas de Pedido — lo que Compras le manda al proveedor para
// confirmar una cotización cuando hay urgencia (no da tiempo el
// circuito normal de Orden de Compra) o se contrata un servicio (que
// después genera una OTT y su propia OC). Antes se armaba a mano en
// Word, numerado a mano, sin seguimiento — acá se numeran solas
// (secuencia real de Postgres, sql/007_notas_pedido.sql) y se genera
// el PDF para descargar.
//
// Seguimiento = vínculo simple con una Orden de Compra: la NP queda
// PENDIENTE hasta que se la vincula a un N° de OC ya cargado
// (compras_oc_lineas.orden_compra), pasa a VINCULADA. No replica el
// cálculo pendiente/parcial/completada de OC — eso lo sigue
// mostrando el módulo de Órdenes de Compra. Ver CLAUDE.md.
// ============================================================
import { SB } from '../supabase-client.js';
import { toast, om, cm, fmt, today, fetchAll, escAttr, escJsArg } from '../utils.js';
import { getUsuarioActual } from '../login.js';

let NOTAS = [];
let PROVEEDORES = [];
let OC_LINEAS_MIN = []; // solo orden_compra + proveedor_nombre, para sugerir al vincular

function simboloMoneda(moneda) {
  return moneda === 'USD' ? 'U$S' : '$';
}
function fmtPesos(n, moneda) {
  // "$" pegado al número (sin espacio) — con espacio normal, una celda
  // angosta del PDF cortaba la línea justo ahí y el símbolo quedaba solo
  // arriba del monto. "U$S" en cambio sí necesita separación para leerse
  // bien, así que usa un espacio DURO (no se parte nunca, ni en el PDF).
  const sep = moneda === 'USD' ? ' ' : '';
  return simboloMoneda(moneda) + sep + Number(n || 0).toLocaleString('es-AR', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
}

// Subtotal de cada ítem (cantidad × precio, ambos numéricos) y el total
// con la bonificación aplicada — usado en vivo en el modal, en el detalle
// de la lista y en el PDF, para no repetir la cuenta en tres lugares.
function calcularTotales(items, bonifPct) {
  const subtotal = (Array.isArray(items) ? items : []).reduce((s, it) => s + (Number(it.cantidad) || 0) * (Number(it.precio) || 0), 0);
  const pct = Number(bonifPct) || 0;
  const montoBonif = subtotal * (pct / 100);
  const total = subtotal - montoBonif;
  return { subtotal, pct, montoBonif, total };
}

