// ------------------------------------------------------------
// Carga de datos
// ------------------------------------------------------------
async function cargarTodo() {
  const [np, pv, oc] = await Promise.all([
    fetchAll(() => SB.from('compras_notas_pedido').select('*').order('numero', { ascending: false })),
    SB.from('compras_proveedores').select('id,nombre').order('nombre'),
    fetchAll(() => SB.from('compras_oc_lineas').select('orden_compra,proveedor_nombre,fecha,importe,cant_recibida,cant_pendiente,precio_unitario,articulo_desc,cant_pedida')),
  ]);
  const error = np.error || pv.error || oc.error;
  if (error) throw error;

  NOTAS = np.data || [];
  PROVEEDORES = pv.data || [];
  OC_LINEAS_MIN = oc.data || [];
}

// Agrupa las líneas de compras_oc_lineas por N° de orden — mismo criterio
// que agruparPorOrden()/estadoOC() en js/modules/oc.js (duplicado a
// propósito, mismo patrón que initExpandCollapse en el resto de módulos).
function agruparOCPorOrden() {
  const map = new Map();
  for (const l of OC_LINEAS_MIN) {
    if (!l.orden_compra) continue;
    if (!map.has(l.orden_compra)) {
      map.set(l.orden_compra, { orden_compra: l.orden_compra, proveedor_nombre: l.proveedor_nombre, fecha: l.fecha, importe: 0, algunaRecibida: false, algunaPendiente: false, lineas: [] });
    }
    const g = map.get(l.orden_compra);
    g.importe += l.importe || 0;
    if ((l.cant_recibida || 0) > 0.01) g.algunaRecibida = true;
    if ((l.cant_pendiente || 0) > 0.01) g.algunaPendiente = true;
    if (l.fecha && (!g.fecha || l.fecha < g.fecha)) g.fecha = l.fecha;
    g.lineas.push({ descripcion: l.articulo_desc, cantidad: l.cant_pedida, importe: l.importe });
  }
  return [...map.values()].map(g => ({
    ...g,
    estado: !g.algunaRecibida ? 'PENDIENTE' : (!g.algunaPendiente ? 'COMPLETADA' : 'PARCIAL'),
  }));
}

// ------------------------------------------------------------
// Helpers
// ------------------------------------------------------------
function diasDesde(fechaISO) {
  if (!fechaISO) return 0;
  return Math.floor((new Date(today() + 'T00:00:00') - new Date(fechaISO + 'T00:00:00')) / 86400000);
}

function claseAntiguedad(dias) {
  if (dias >= 10) return 'vencido';
  if (dias >= 5) return 'porvencer';
  return 'vigente';
}

function initExpandCollapse(tbodyId) {
  document.getElementById(tbodyId)?.addEventListener('click', e => {
    if (e.target.closest('.sto-accion')) return;
    const row = e.target.closest('.oc-row');
    if (!row) return;
    const detailRow = row.nextElementSibling;
    if (!detailRow || !detailRow.classList.contains('oc-detail')) return;
    const isOpen = detailRow.style.display !== 'none';
    detailRow.style.display = isOpen ? 'none' : '';
    const chevron = row.querySelector('.oc-chevron');
    if (chevron) chevron.textContent = isOpen ? '▸' : '▾';
  });
}

// ------------------------------------------------------------
// Lista
// ------------------------------------------------------------
// Nombres sugeridos para el campo Proveedor: tanto los que tienen ficha
// propia (compras_proveedores) como los que solo aparecen en Órdenes de
// Compra — así "Sherwin" sugiere "SHERWIN WILLIAMS ARGENTINA ICSA" aunque
// nunca se le haya dado de alta en el catálogo. Sigue siendo texto libre:
// si no coincide con nada de la lista, se guarda tal cual se escriba.
function nombresProveedoresSugeridos() {
  return [...new Set([
    ...PROVEEDORES.map(p => p.nombre),
    ...OC_LINEAS_MIN.map(l => l.proveedor_nombre),
  ].filter(Boolean))].sort((a, b) => a.localeCompare(b, 'es'));
}

// Autocomplete propio (no <datalist> nativo — mezclaba con el historial
// de autocompletado del navegador y se veía feo/sin estilo).
function filtrarSugerenciasProveedor() {
  const input = document.getElementById('np_proveedor');
  const box = document.getElementById('np_proveedor_sug');
  if (!input || !box) return;
  const q = input.value.trim().toUpperCase();
  if (!q) { box.style.display = 'none'; box.innerHTML = ''; return; }
  const coincidencias = nombresProveedoresSugeridos().filter(n => n.toUpperCase().includes(q)).slice(0, 8);
  if (!coincidencias.length) { box.style.display = 'none'; box.innerHTML = ''; return; }
  box.innerHTML = coincidencias.map(n => `<div class="ac-item" data-nombre="${escAttr(n)}">${escAttr(n)}</div>`).join('');
  box.style.display = '';
}

function initAutocompleteProveedor() {
  const input = document.getElementById('np_proveedor');
  const box = document.getElementById('np_proveedor_sug');
  if (!input || !box) return;
  input.addEventListener('input', filtrarSugerenciasProveedor);
  input.addEventListener('focus', filtrarSugerenciasProveedor);
  box.addEventListener('mousedown', e => {
    const item = e.target.closest('.ac-item');
    if (!item) return;
    e.preventDefault();
    input.value = item.dataset.nombre;
    box.style.display = 'none';
  });
  // Cierra al hacer click afuera (con un pequeño delay para no pisar el mousedown del item).
  input.addEventListener('blur', () => setTimeout(() => { box.style.display = 'none'; }, 120));
}

function filaDetalleNota(n) {
  const items = Array.isArray(n.items) ? n.items : [];
  const { subtotal, pct, montoBonif, total } = calcularTotales(items, n.bonificacion);
  const filasItems = items.length
    ? items.map(it => `<tr><td style="text-align:center">${escAttr(it.cantidad || '')}</td><td style="text-align:center">${escAttr(it.unidad || '')}</td><td>${escAttr(it.descripcion || '')}</td><td style="text-align:center">${fmtPesos(it.precio, n.moneda)}</td><td style="text-align:center">${fmtPesos((Number(it.cantidad) || 0) * (Number(it.precio) || 0), n.moneda)}</td></tr>`).join('')
    : '<tr><td colspan="5" style="color:var(--muted)">Sin ítems cargados</td></tr>';
  const campo = (label, val) => val ? `<div><strong>${label}:</strong> ${escAttr(val)}</div>` : '';
  return `
    <div class="tw" style="margin-bottom:10px"><table>
      <thead><tr><th>Cantidad</th><th>Unidad</th><th>Descripción</th><th style="text-align:center">Precio</th><th style="text-align:center">Subtotal</th></tr></thead>
      <tbody>${filasItems}</tbody>
    </table></div>
    <div style="display:flex;flex-direction:column;gap:4px;font-size:13px;max-width:280px;margin-bottom:10px">
      <div style="display:flex;justify-content:space-between"><span>Subtotal</span><strong>${fmtPesos(subtotal, n.moneda)}</strong></div>
      ${pct ? `<div style="display:flex;justify-content:space-between;color:var(--muted)"><span>Bonificación (${pct}%)</span><span>-${fmtPesos(montoBonif, n.moneda)}</span></div>` : ''}
      <div style="display:flex;justify-content:space-between;border-top:1px solid var(--border);padding-top:4px"><span>Total${n.mas_iva ? ' (+ IVA)' : ''}</span><strong>${fmtPesos(total, n.moneda)}</strong></div>
    </div>
    <div style="display:flex;flex-direction:column;gap:4px;font-size:13px">
      ${campo('Entrega parcial', n.entrega_parcial)}
      ${campo('Fecha de entrega', n.fecha_entrega ? fmt(n.fecha_entrega) : '')}
      ${campo('Condiciones de pago', n.condiciones_pago)}
      ${campo('Lugar de entrega', n.lugar_entrega)}
      ${campo('N°/código de cotización', n.cotizacion_ref)}
      ${campo('Adjuntos', n.adjuntos)}
      ${campo('Autorizado por', n.revisado_por)}
      ${n.estado === 'VINCULADA' ? `<div><strong>Vinculada a OC:</strong> ${escAttr(n.orden_compra_vinculada || '')}${n.vinculada_en ? ` (${fmt(n.vinculada_en.slice(0, 10))})` : ''}</div>` : ''}
    </div>`;
}

function renderLista() {
  const estadoFiltro = document.getElementById('np_f_estado')?.value ?? 'PENDIENTE';
  const q = (document.getElementById('np_f_q')?.value || '').trim().toUpperCase();

  let lista = NOTAS;
  if (estadoFiltro) lista = lista.filter(n => n.estado === estadoFiltro);
  if (q) lista = lista.filter(n => (n.proveedor_nombre || '').toUpperCase().includes(q) || String(n.numero).includes(q));

  const resumen = document.getElementById('np_resumen');
  if (resumen) {
    const pend = NOTAS.filter(n => n.estado === 'PENDIENTE').length;
    const vinc = NOTAS.filter(n => n.estado === 'VINCULADA').length;
    resumen.textContent = `${pend} pendiente${pend === 1 ? '' : 's'} · ${vinc} vinculada${vinc === 1 ? '' : 's'}`;
  }

  const tb = document.getElementById('t-np-lista');
  if (!tb) return;
  if (!lista.length) { tb.innerHTML = '<tr><td colspan="6" style="text-align:center;padding:18px;color:var(--muted)">Sin notas de pedido</td></tr>'; return; }

  tb.innerHTML = lista.map(n => {
    const dias = diasDesde(n.fecha);
    const antig = n.estado === 'PENDIENTE' ? `<span class="badge ${claseAntiguedad(dias)}">hace ${dias} día${dias === 1 ? '' : 's'}</span>` : '';
    const estadoBadge = n.estado === 'PENDIENTE' ? '<span class="badge pendiente">Pendiente</span>' : '<span class="badge comp">Vinculada</span>';
    const accionVinculo = n.estado === 'PENDIENTE'
      ? `<button class="bsm sto-accion" onclick="window.notasPedido.vincularOC('${n.id}')">🔗 Vincular OC</button>`
      : `<button class="bsm sto-accion" onclick="window.notasPedido.desvincular('${n.id}')">Desvincular (OC ${escAttr(n.orden_compra_vinculada || '')})</button>`;
    return `<tr class="oc-row">
      <td><span class="oc-chevron">▸</span> ${n.numero}</td>
      <td>${fmt(n.fecha)}</td>
      <td>${escAttr(n.proveedor_nombre)}</td>
      <td>${n.ot ? escAttr(n.ot) : '–'}</td>
      <td>${estadoBadge} ${antig}</td>
      <td>
        <button class="bsm sto-accion" onclick="window.notasPedido.descargarPdf('${n.id}')">📄 PDF</button>
        ${accionVinculo}
        <button class="bsm d sto-accion" onclick="window.notasPedido.eliminarNota('${n.id}')">🗑️</button>
      </td>
    </tr>
    <tr class="oc-detail" style="display:none"><td colspan="6">${filaDetalleNota(n)}</td></tr>`;
  }).join('');
}

// ------------------------------------------------------------
// Alta — modal con ítems dinámicos
// ------------------------------------------------------------
const UNIDADES = ['Unidad', 'KG', 'Mts', 'Lts', 'Mt2'];

function filaItemInput() {
  const opciones = `<option value=""></option>` + UNIDADES.map(u => `<option value="${u}">${u}</option>`).join('');
  return `<tr>
    <td><input class="np-it-cant" type="number" min="0" step="any" placeholder="Cant." style="text-align:center"></td>
    <td><select class="np-it-uni">${opciones}</select></td>
    <td><input class="np-it-desc" placeholder="Descripción"></td>
    <td><input class="np-it-precio" type="number" min="0" step="any" placeholder="Precio" style="text-align:center"></td>
    <td class="np-it-subtotal" style="color:var(--muted);white-space:nowrap;text-align:center">$0,00</td>
    <td><button type="button" class="bsm d np-it-del">🗑️</button></td>
  </tr>`;
}

function agregarFilaItem() {
  document.getElementById('np_items_body')?.insertAdjacentHTML('beforeend', filaItemInput());
}

function leerItemsDelForm() {
  return [...document.querySelectorAll('#np_items_body tr')].map(tr => ({
    cantidad: Number(tr.querySelector('.np-it-cant').value) || 0,
    unidad: tr.querySelector('.np-it-uni').value.trim(),
    descripcion: tr.querySelector('.np-it-desc').value.trim(),
    precio: Number(tr.querySelector('.np-it-precio').value) || 0,
  })).filter(it => it.cantidad || it.unidad || it.descripcion || it.precio);
}

// Recalcula subtotal por fila y el resumen (Subtotal / Bonificación / Total)
// en vivo mientras se completa el formulario — mismo cálculo que usan
// filaDetalleNota() y el PDF, para que el modal muestre exactamente lo que
// va a terminar en el documento.
function recalcularTotalesModal() {
  const moneda = document.getElementById('np_moneda')?.value || 'ARS';
  document.querySelectorAll('#np_items_body tr').forEach(tr => {
    const cant = Number(tr.querySelector('.np-it-cant').value) || 0;
    const precio = Number(tr.querySelector('.np-it-precio').value) || 0;
    const celda = tr.querySelector('.np-it-subtotal');
    if (celda) celda.textContent = fmtPesos(cant * precio, moneda);
  });

  const items = leerItemsDelForm();
  const bonifPct = document.getElementById('np_bonificacion')?.value || 0;
  const { subtotal, pct, montoBonif, total } = calcularTotales(items, bonifPct);

  const set = (id, val) => { const el = document.getElementById(id); if (el) el.textContent = val; };
  set('np_tot_subtotal', fmtPesos(subtotal, moneda));
  set('np_tot_bonif_pct', pct);
  set('np_tot_bonif_monto', '-' + fmtPesos(montoBonif, moneda));
  set('np_tot_total', fmtPesos(total, moneda));
  const bonifRow = document.getElementById('np_tot_bonif_row');
  if (bonifRow) bonifRow.style.display = pct ? '' : 'none';
  const ivaTag = document.getElementById('np_tot_iva_tag');
  if (ivaTag) ivaTag.textContent = document.getElementById('np_mas_iva')?.checked ? ' (+ IVA)' : '';
}

function abrirNuevaNota() {
  document.getElementById('fNOTAPEDIDO')?.reset();
  const sug = document.getElementById('np_proveedor_sug');
  if (sug) sug.style.display = 'none';
  const fecha = document.getElementById('np_fecha');
  if (fecha) fecha.value = today();
  const iva = document.getElementById('np_mas_iva');
  if (iva) iva.checked = true;
  const tb = document.getElementById('np_items_body');
  if (tb) tb.innerHTML = '';
  agregarFilaItem();
  const revisadoPor = document.getElementById('np_revisado_por');
  if (revisadoPor) revisadoPor.textContent = getUsuarioActual()?.nombre || '–';
  const chk = document.getElementById('np_entrega_parcial_chk');
  const detalle = document.getElementById('np_entrega_parcial_detalle');
  if (chk) chk.checked = false;
  if (detalle) { detalle.style.display = 'none'; detalle.value = ''; }
  const bonif = document.getElementById('np_bonificacion');
  if (bonif) bonif.value = '';
  const moneda = document.getElementById('np_moneda');
  if (moneda) moneda.value = 'ARS';
  // Estimado a partir de la NP más alta ya cargada — el número real lo
  // asigna la secuencia de Postgres recién al guardar (ver 8.1), así que
  // esto es solo una vista previa, no una garantía si otra persona crea
  // una NP en el medio.
  const preview = document.getElementById('np_numero_preview');
  if (preview) {
    const maxNum = NOTAS.reduce((m, x) => Math.max(m, x.numero || 0), 0);
    preview.textContent = maxNum ? `— N° ${maxNum + 1} (estimado)` : '';
  }
  recalcularTotalesModal();
  om('mNOTAPEDIDO');
}

function leerFotoComoDataUrl(file) {
  if (!file) return Promise.resolve(null);
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = () => resolve(reader.result);
    reader.onerror = () => reject(reader.error);
    reader.readAsDataURL(file);
  });
}

async function guardarNota(e) {
  e.preventDefault();
  const proveedor_nombre = document.getElementById('np_proveedor').value.trim();
  if (!proveedor_nombre) { toast('Elegí un proveedor', 'er'); return; }

  const entregaParcialChk = document.getElementById('np_entrega_parcial_chk').checked;
  const fotoInput = document.getElementById('np_adjunto_foto');
  const fotoFile = fotoInput?.files?.[0] || null;
  let adjuntos = document.getElementById('np_adjuntos').value.trim() || null;
  if (fotoFile) adjuntos = (adjuntos ? adjuntos + ' — ' : '') + `foto adjunta: ${fotoFile.name}`;

  const proveedor = PROVEEDORES.find(p => p.nombre === proveedor_nombre);
  const payload = {
    proveedor_id: proveedor ? proveedor.id : null,
    proveedor_nombre,
    fecha: document.getElementById('np_fecha').value || today(),
    ot: document.getElementById('np_ot').value.trim() || null,
    cotizacion_ref: document.getElementById('np_cotizacion_ref').value.trim() || null,
    items: leerItemsDelForm(),
    moneda: document.getElementById('np_moneda').value || 'ARS',
    mas_iva: document.getElementById('np_mas_iva').checked,
    bonificacion: document.getElementById('np_bonificacion').value.trim() || null,
    fecha_entrega: document.getElementById('np_fecha_entrega').value || null,
    entrega_parcial: entregaParcialChk ? (document.getElementById('np_entrega_parcial_detalle').value.trim() || null) : null,
    condiciones_pago: document.getElementById('np_condiciones_pago').value || null,
    lugar_entrega: document.getElementById('np_lugar_entrega').value.trim() || null,
    adjuntos,
    revisado_por: getUsuarioActual()?.nombre || null,
  };

  const { data, error } = await SB.from('compras_notas_pedido').insert(payload).select().single();
  if (error) { toast(error.message, 'er'); return; }

  NOTAS.unshift(data);
  cm('mNOTAPEDIDO');
  toast(`✓ Nota de Pedido N° ${data.numero} creada`);
  // La foto NUNCA se guarda en la base — solo se usa acá, en el momento, para
  // meterla en el PDF que se descarga ahora. Si se vuelve a descargar el PDF
  // más adelante desde la lista, ya no va a estar (queda el aviso en "adjuntos").
  const fotoDataUrl = await leerFotoComoDataUrl(fotoFile).catch(() => null);
  generarPdfNP(data, fotoDataUrl);
  renderLista();
}

// ------------------------------------------------------------
// Vincular / desvincular con Orden de Compra (seguimiento)
// ------------------------------------------------------------
// ------------------------------------------------------------
// Vincular con OC — modal con buscador (no prompt()): por defecto
// filtra por el proveedor de la NP, para poder elegir de una entre sus
// OC ya cargadas; se puede buscar cualquier otro proveedor/N° de OC.
// ------------------------------------------------------------
let NP_A_VINCULAR = null;

const ESTADO_OC_LABEL = { PENDIENTE: 'Pendiente', PARCIAL: 'Parcial', COMPLETADA: 'Completada' };
const ESTADO_OC_CLASE = { PENDIENTE: 'vencido', PARCIAL: 'porvencer', COMPLETADA: 'vigente' };

function renderListaVincularOC() {
  const q = (document.getElementById('voc_f_q')?.value || '').trim().toUpperCase();
  let ordenes = agruparOCPorOrden();
  if (q) ordenes = ordenes.filter(o => (o.proveedor_nombre || '').toUpperCase().includes(q) || String(o.orden_compra).toUpperCase().includes(q));
  ordenes.sort((a, b) => (b.fecha || '').localeCompare(a.fecha || ''));
  ordenes = ordenes.slice(0, 200);

  const resumen = document.getElementById('voc_resumen');
  if (resumen) resumen.textContent = `${ordenes.length} orden${ordenes.length === 1 ? '' : 'es'} de compra${ordenes.length === 200 ? ' (mostrando las primeras 200 — afiná la búsqueda)' : ''}`;

  const tb = document.getElementById('voc_lista');
  if (!tb) return;
  if (!ordenes.length) { tb.innerHTML = '<tr><td colspan="6" style="text-align:center;padding:18px;color:var(--muted)">Sin resultados</td></tr>'; return; }

  tb.innerHTML = ordenes.map(o => {
    const filasArt = (o.lineas || []).map(l => `<tr>
      <td>${escAttr(l.descripcion || '(sin descripción)')}</td>
      <td style="text-align:center">${l.cantidad ?? '–'}</td>
      <td style="text-align:right">${fmtPesos(l.importe)}</td>
    </tr>`).join('');
    return `<tr class="oc-row">
      <td><span class="oc-chevron">▸</span> ${escAttr(o.orden_compra)}</td>
      <td>${escAttr(o.proveedor_nombre || '–')}</td>
      <td>${o.fecha ? fmt(o.fecha) : '–'}</td>
      <td>${fmtPesos(o.importe)}</td>
      <td><span class="badge ${ESTADO_OC_CLASE[o.estado]}">${ESTADO_OC_LABEL[o.estado]}</span></td>
      <td><button type="button" class="bsm p sto-accion" onclick="window.notasPedido.confirmarVincularOC('${escJsArg(o.orden_compra)}')">Vincular</button></td>
    </tr>
    <tr class="oc-detail" style="display:none"><td colspan="6">
      <div class="tw"><table>
        <thead><tr><th>Qué se compró</th><th style="text-align:center">Cantidad</th><th style="text-align:right">Importe</th></tr></thead>
        <tbody>${filasArt || '<tr><td colspan="3" style="color:var(--muted)">Sin detalle de artículos</td></tr>'}</tbody>
      </table></div>
    </td></tr>`;
  }).join('');
}

function vincularOC(id) {
  const n = NOTAS.find(x => x.id === id);
  if (!n) return;
  NP_A_VINCULAR = id;
  document.getElementById('mVOC_t').textContent = `Vincular NP ${n.numero} (${n.proveedor_nombre}) con Orden de Compra`;
  const q = document.getElementById('voc_f_q');
  if (q) q.value = n.proveedor_nombre || '';
  renderListaVincularOC();
  om('mVINCULAROC');
}

async function confirmarVincularOC(numeroOC) {
  const id = NP_A_VINCULAR;
  const n = NOTAS.find(x => x.id === id);
  if (!id || !n) return;

  const { data, error } = await SB.from('compras_notas_pedido')
    .update({ estado: 'VINCULADA', orden_compra_vinculada: numeroOC, vinculada_en: new Date().toISOString() })
    .eq('id', id).select().single();
  if (error) { toast(error.message, 'er'); return; }

  NOTAS = NOTAS.map(x => x.id === id ? data : x);
  cm('mVINCULAROC');
  toast(`✓ NP ${n.numero} vinculada a OC ${numeroOC}`);
  renderLista();
}

async function desvincular(id) {
  const n = NOTAS.find(x => x.id === id);
  if (!n) return;
  if (!confirm(`¿Desvincular la NP ${n.numero} de la OC ${n.orden_compra_vinculada}? Vuelve a quedar Pendiente.`)) return;

  const { data, error } = await SB.from('compras_notas_pedido')
    .update({ estado: 'PENDIENTE', orden_compra_vinculada: null, vinculada_en: null })
    .eq('id', id).select().single();
  if (error) { toast(error.message, 'er'); return; }

  NOTAS = NOTAS.map(x => x.id === id ? data : x);
  toast('Desvinculada — vuelve a estar Pendiente');
  renderLista();
}

async function eliminarNota(id) {
  const n = NOTAS.find(x => x.id === id);
  if (!n) return;
  if (!confirm(`¿Eliminar la Nota de Pedido N° ${n.numero}? No se puede deshacer.`)) return;

  const { error } = await SB.from('compras_notas_pedido').delete().eq('id', id);
  if (error) { toast(error.message, 'er'); return; }

  NOTAS = NOTAS.filter(x => x.id !== id);
  toast('Eliminada');
  renderLista();
}

// ------------------------------------------------------------
// PDF — jsPDF + jspdf-autotable (CDN, cargados en index.html), mismo
// criterio "sin bundler" que SheetJS/Chart.js en OC/Stock.
// ------------------------------------------------------------
function descargarPdf(id) {
  const n = NOTAS.find(x => x.id === id);
  if (n) generarPdfNP(n);
}

function dimensionesImagen(dataUrl) {
  return new Promise((resolve) => {
    const img = new Image();
    img.onload = () => resolve({ width: img.naturalWidth, height: img.naturalHeight });
    img.onerror = () => resolve(null);
    img.src = dataUrl;
  });
}

async function generarPdfNP(n, fotoDataUrl) {
  const { jsPDF } = window.jspdf;
  const doc = new jsPDF({ unit: 'mm', format: 'a4' });
  const marginX = 15;
  const pageW = 210;
  let y = 18;

  // Logo (666×310px original → se mantiene la proporción ~2.15:1). Más
  // espacio contra la dirección/mail de lo que había antes (quedaba muy
  // pegado) — pedido explícito del usuario.
  doc.addImage(EMPRESA.logoBase64, 'PNG', marginX, y - 6, 38, 17.7);
  doc.setFont('helvetica', 'normal'); doc.setFontSize(9); doc.setTextColor(100);
  doc.text(EMPRESA.direccion, marginX, y + 17);
  const emailsText = EMPRESA.emails.join('   ·   ');
  doc.text(emailsText, marginX, y + 23);
  // Mail clickeable — un solo link que cubre las dos direcciones (van las
  // dos como destinatarias, "para" ambas a la vez).
  doc.link(marginX, y + 23 - 3.2, doc.getTextWidth(emailsText), 4, { url: `mailto:${EMPRESA.emails.join(',')}` });

  doc.setTextColor(0);
  doc.setFont('helvetica', 'bold'); doc.setFontSize(18);
  doc.text('NOTA DE PEDIDO', pageW - marginX, y, { align: 'right' });
  doc.setFontSize(13);
  doc.text(`N° ${n.numero}`, pageW - marginX, y + 7, { align: 'right' });
  doc.setFont('helvetica', 'normal'); doc.setFontSize(10);
  doc.text(`Fecha: ${fmt(n.fecha)}`, pageW - marginX, y + 13, { align: 'right' });

  y += 30;
  doc.setDrawColor(200); doc.line(marginX, y, pageW - marginX, y);
  y += 8;

  doc.setFont('helvetica', 'bold'); doc.setFontSize(11); doc.setTextColor(0);
  doc.text('Sres.', marginX, y);
  doc.setFont('helvetica', 'normal');
  doc.text(n.proveedor_nombre || '', marginX + 14, y);
  if (n.ot) {
    doc.setFont('helvetica', 'bold');
    doc.text('O.T.:', 140, y);
    doc.setFont('helvetica', 'normal');
    doc.text(String(n.ot), 152, y);
  }
  y += 9;

  // Datos operativos, agrupados debajo de "Sres." — pedido explícito del
  // usuario en vez de dejarlos sueltos al final del documento. Cada lado
  // puede envolver a varias líneas (ej. "Entrega parcial" es texto libre)
  // así que la fila avanza según el lado que necesite más renglones.
  const colDerX = pageW / 2 + 5;
  const filaInfo = (labelIzq, valIzq, labelDer, valDer) => {
    if (!valIzq && !valDer) return;
    doc.setFontSize(9);
    let lineasIzq = 1, lineasDer = 1;
    if (valIzq) {
      doc.setFont('helvetica', 'bold'); doc.setTextColor(0);
      doc.text(`${labelIzq}:`, marginX, y);
      doc.setFont('helvetica', 'normal');
      const w = doc.splitTextToSize(String(valIzq), colDerX - marginX - 34 - 4);
      doc.text(w, marginX + 34, y);
      lineasIzq = w.length;
    }
    if (valDer) {
      doc.setFont('helvetica', 'bold'); doc.setTextColor(0);
      doc.text(`${labelDer}:`, colDerX, y);
      doc.setFont('helvetica', 'normal');
      const w = doc.splitTextToSize(String(valDer), pageW - marginX - colDerX - 34);
      doc.text(w, colDerX + 34, y);
      lineasDer = w.length;
    }
    y += 6 * Math.max(lineasIzq, lineasDer);
  };
  // Orden pedido explícitamente por el usuario: Entrega parcial primero,
  // después Fecha de entrega, después Lugar de entrega (columna
  // izquierda) — Condiciones de pago y Autorizado por a la derecha.
  filaInfo('Entrega parcial', n.entrega_parcial, 'Condiciones de pago', n.condiciones_pago);
  filaInfo('Fecha de entrega', n.fecha_entrega ? fmt(n.fecha_entrega) : '', 'Autorizado por', n.revisado_por);
  filaInfo('Lugar de entrega', n.lugar_entrega, '', '');
  if (n.cotizacion_ref) {
    doc.setFont('helvetica', 'bold'); doc.setFontSize(9); doc.setTextColor(0);
    doc.text('N°/código de cotización:', marginX, y);
    doc.setFont('helvetica', 'normal');
    doc.text(String(n.cotizacion_ref), marginX + 46, y);
    y += 6;
  }
  y += 4;

  const items = Array.isArray(n.items) ? n.items : [];
  const totales = calcularTotales(items, n.bonificacion);
  doc.autoTable({
    startY: y,
    margin: { left: marginX, right: marginX },
    head: [['Cantidad', 'Unidad', 'Descripción', 'Precio', 'Subtotal']],
    body: items.length
      ? items.map(it => [it.cantidad || '', it.unidad || '', it.descripcion || '', fmtPesos(it.precio, n.moneda), fmtPesos((Number(it.cantidad) || 0) * (Number(it.precio) || 0), n.moneda)])
      : [['—', '—', 'Sin ítems cargados', '—', '—']],
    styles: { fontSize: 9, cellPadding: 2.5 },
    headStyles: { fillColor: [30, 41, 59], halign: 'center' },
    columnStyles: { 0: { halign: 'center' }, 1: { halign: 'center' }, 3: { halign: 'center' }, 4: { halign: 'center' } },
  });
  y = doc.lastAutoTable.finalY + 8;

  // Resumen de totales, alineado a la derecha como en cualquier
  // presupuesto — Subtotal / Bonificación (si hay) / Total con el
  // descuento aplicado, aclarando si es + IVA o no.
  const labelX = pageW - marginX - 65;
  const valX = pageW - marginX;
  doc.setTextColor(0); doc.setFont('helvetica', 'normal'); doc.setFontSize(10);
  doc.text('Subtotal', labelX, y);
  doc.text(fmtPesos(totales.subtotal, n.moneda), valX, y, { align: 'right' });
  y += 6;
  if (totales.pct) {
    doc.setTextColor(100);
    doc.text(`Bonificación (${totales.pct}%)`, labelX, y);
    doc.text('-' + fmtPesos(totales.montoBonif, n.moneda), valX, y, { align: 'right' });
    doc.setTextColor(0);
    y += 6;
  }
  doc.setDrawColor(200); doc.line(labelX, y, valX, y);
  y += 5;
  doc.setFont('helvetica', 'bold'); doc.setFontSize(12);
  doc.text(`Total${n.mas_iva ? ' (+ IVA)' : ''}`, labelX, y);
  doc.text(fmtPesos(totales.total, n.moneda), valX, y, { align: 'right' });
  y += 12;

  doc.setDrawColor(220); doc.line(marginX, y, pageW - marginX, y);
  y += 6;
  doc.setFont('helvetica', 'italic'); doc.setFontSize(8); doc.setTextColor(100);
  const legal = 'Aceptación de la Nota de Pedido: si dentro de los dos (2) días corridos siguientes a la fecha de la presente no recibimos comunicación escrita objetando las condiciones particulares o generales, se entiende aceptada en todos sus términos.';
  doc.text(doc.splitTextToSize(legal, pageW - marginX * 2), marginX, y);

  // La foto (si se cargó) va en una página aparte, escalada dentro de la
  // hoja preservando proporción — nunca se guarda en la base, solo vive
  // acá en el momento de armar este PDF puntual.
  if (fotoDataUrl) {
    const dim = await dimensionesImagen(fotoDataUrl);
    doc.addPage();
    doc.setFont('helvetica', 'bold'); doc.setFontSize(11); doc.setTextColor(0);
    doc.text('Adjunto', marginX, 18);
    if (dim) {
      const maxW = pageW - marginX * 2;
      const maxH = 297 - 30;
      const escala = Math.min(maxW / dim.width, maxH / dim.height);
      const w = dim.width * escala;
      const h = dim.height * escala;
      doc.addImage(fotoDataUrl, marginX, 26, w, h);
    }
  }

  doc.save(`NP-${n.numero}.pdf`);
}

// ------------------------------------------------------------
export async function render(secId) {
  if (secId !== 'np-lista') return;
  const tb = document.getElementById('t-np-lista');
  if (tb) tb.innerHTML = '<tr><td colspan="6" class="loading">Cargando...</td></tr>';
  try {
    await cargarTodo();
  } catch (error) {
    if (tb) tb.innerHTML = `<tr><td colspan="6" style="color:var(--red);padding:12px">${error.message}</td></tr>`;
    return;
  }
  renderLista();
}

export function init() {
  document.getElementById('np_nuevo')?.addEventListener('click', abrirNuevaNota);
  document.getElementById('np_add_item')?.addEventListener('click', () => { agregarFilaItem(); recalcularTotalesModal(); });
  document.getElementById('np_items_body')?.addEventListener('click', e => {
    if (e.target.closest('.np-it-del')) { e.target.closest('tr')?.remove(); recalcularTotalesModal(); }
  });
  document.getElementById('np_items_body')?.addEventListener('input', e => {
    if (e.target.classList.contains('np-it-cant') || e.target.classList.contains('np-it-precio')) recalcularTotalesModal();
  });
  document.getElementById('np_bonificacion')?.addEventListener('input', recalcularTotalesModal);
  document.getElementById('np_moneda')?.addEventListener('change', recalcularTotalesModal);
  document.getElementById('np_mas_iva')?.addEventListener('change', recalcularTotalesModal);
  document.getElementById('fNOTAPEDIDO')?.addEventListener('submit', guardarNota);
  // Enter en cualquier campo (ej. tipeando el proveedor o una descripción)
  // no debe mandar la NP a mitad de completar el formulario — solo el
  // botón "Guardar y generar PDF" (o Enter con foco puesto ahí) confirma.
  document.getElementById('fNOTAPEDIDO')?.addEventListener('keydown', e => {
    if (e.key === 'Enter' && e.target.tagName !== 'TEXTAREA' && e.target.type !== 'submit') e.preventDefault();
  });
  document.getElementById('np_entrega_parcial_chk')?.addEventListener('change', e => {
    const detalle = document.getElementById('np_entrega_parcial_detalle');
    if (detalle) detalle.style.display = e.target.checked ? '' : 'none';
  });
  document.getElementById('np_f_estado')?.addEventListener('change', renderLista);
  document.getElementById('np_f_q')?.addEventListener('input', renderLista);
  document.getElementById('voc_f_q')?.addEventListener('input', renderListaVincularOC);
  initExpandCollapse('t-np-lista');
  initExpandCollapse('voc_lista');
  initAutocompleteProveedor();

  window.notasPedido = { descargarPdf, vincularOC, confirmarVincularOC, desvincular, eliminarNota };
}
